import type { Metadata } from "next";
import { getTool, getToolPath } from "./tools";
import { siteAuthor, siteName, siteUrl } from "./site";

// One image per page, generated by scripts/og/generate-og-images.py into public/og/.
export function ogImageFor(path: string, alt: string) {
  const key = path.replace(/^\/+|\/+$/g, "").replace(/\//g, "--") || "home";
  return { url: `/og/${key}.png`, width: 1200, height: 630, alt };
}

const sharedMetadata: Pick<Metadata, "authors" | "creator" | "publisher"> = {
  authors: [{ name: siteAuthor.name, url: `${siteUrl}/about` }],
  creator: siteName,
  publisher: siteName,
};

export function createToolMetadata(slug: string): Metadata {
  const tool = getTool(slug);
  const canonicalPath = getToolPath(tool);
  const ogImage = ogImageFor(canonicalPath, `${tool.name} – SolveGrid`);

  return {
    ...sharedMetadata,
    title: tool.title,
    description: tool.description,
    keywords: tool.keywords,
    alternates: {
      canonical: canonicalPath,
    },
    openGraph: {
      type: "website",
      siteName,
      locale: "en_US",
      title: `${tool.title} | ${siteName}`,
      description: tool.description,
      url: canonicalPath,
      images: [ogImage],
    },
    twitter: {
      card: "summary_large_image",
      title: `${tool.title} | ${siteName}`,
      description: tool.description,
      images: [ogImage.url],
    },
    robots: {
      index: true,
      follow: true,
    },
    other: {
      "application-name": siteName,
      "x-solvegrid-url": `${siteUrl}${canonicalPath}`,
    },
  };
}

export function createStaticPageMetadata(
  title: string,
  description: string,
  canonicalPath: string,
): Metadata {
  const ogImage = ogImageFor(canonicalPath, `${title} – SolveGrid`);
  return {
    ...sharedMetadata,
    title,
    description,
    alternates: { canonical: canonicalPath },
    openGraph: {
      type: "website",
      siteName,
      locale: "en_US",
      title: `${title} | ${siteName}`,
      description,
      url: canonicalPath,
      images: [ogImage],
    },
    twitter: {
      card: "summary_large_image",
      title: `${title} | ${siteName}`,
      description,
      images: [ogImage.url],
    },
    robots: {
      index: true,
      follow: true,
    },
  };
}
